// ==================================================
// Sales Order - True Available Qty (Actual - Reserved)
// ==================================================

frappe.ui.form.on("Sales Order Item", {

    item_code: function (frm, cdt, cdn) {
        update_available_qty(frm, cdt, cdn);
    },

    warehouse: function (frm, cdt, cdn) {
        update_available_qty(frm, cdt, cdn);
    }
});

// --------------------------------------------------
// Fetch Bin and calculate available qty
// --------------------------------------------------
function update_available_qty(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!row.item_code || !row.warehouse) {
        frappe.model.set_value(cdt, cdn, "custom_available_qty", 0);
        return;
    }

    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Bin",
            filters: {
                item_code: row.item_code,
                warehouse: row.warehouse
            },
            fieldname: ["actual_qty", "reserved_qty"]
        },
        callback: function (r) {
            if (r.message) {
                let actual_qty = flt(r.message.actual_qty);
                let reserved_qty = flt(r.message.reserved_qty);

                let available_qty = actual_qty - reserved_qty;

                frappe.model.set_value(
                    cdt,
                    cdn,
                    "custom_available_qty",
                    available_qty
                );
            } else {
                frappe.model.set_value(cdt, cdn, "custom_available_qty", 0);
            }
        }
    });
}

