frappe.ui.form.on("Sales Order Item", {
    item_code(frm, cdt, cdn) {
        calculate_available_qty(frm, cdt, cdn);
    },
    warehouse(frm, cdt, cdn) {
        calculate_available_qty(frm, cdt, cdn);
    }
});

function calculate_available_qty(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    if (!row.item_code || !row.warehouse) {
        frappe.model.set_value(cdt, cdn, "custom_available_qty", 0);
        return;
    }

    // STEP 1: Get actual stock from Bin
    frappe.call({
        method: "frappe.client.get_value",
        args: {
            doctype: "Bin",
            filters: {
                item_code: row.item_code,
                warehouse: row.warehouse
            },
            fieldname: ["actual_qty"]
        },
        callback(bin_res) {
            let actual_qty = flt(bin_res.message?.actual_qty || 0);

            // STEP 2: Get submitted Stock Reservation Entries
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Stock Reservation Entry",
                    filters: {
                        item_code: row.item_code,
                        warehouse: row.warehouse,
                        docstatus: 1
                    },
                    fields: ["reserved_qty"],
                    limit_page_length: 1000
                },
                callback(sre_res) {
                    let total_reserved = 0;

                    if (sre_res.message && sre_res.message.length) {
                        sre_res.message.forEach(row => {
                            total_reserved += flt(row.reserved_qty);
                        });
                    }

                    // STEP 3: Final available qty
                    let final_available = actual_qty - total_reserved;

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "custom_available_qty",
                        final_available > 0 ? final_available : 0
                    );
                }
            });
        }
    });
}

