frappe.ui.form.on('Feed Scheduling Entry', {
    refresh(frm) { render_if_ready(frm); },
    shed(frm) { render_if_ready(frm); },
    shift_type(frm) { render_if_ready(frm); }
});

function render_if_ready(frm) {
    if (frm.doc.shed && frm.doc.shift_type) {
        render_table(frm);
    } else {
        frm.fields_dict.feed_matrix_html.$wrapper.html("<p>Select Shed & Shift</p>");
    }
}


// 🚀 MAIN
async function render_table(frm) {

    // 1) Tanks with stage
    let tanks = await frappe.db.get_list('Hatchery Tank', {
        filters: { shed: frm.doc.shed },
        fields: ['name', 'stage']
    });

    if (!tanks.length) {
        frm.fields_dict.feed_matrix_html.$wrapper.html("<p>No tanks found</p>");
        return;
    }

    // 2) Times for selected shift
    let times = get_shift_times(frm.doc.shift_type);

    // 3) SOP data (master)
    let sop_data = await get_sop_data(frm.doc.shift_type);

    let html = `<table class="table table-bordered text-center">`;

    // HEADER
    html += `<thead><tr>
        <th style="min-width:120px">Tank</th>`;
    times.forEach(t => html += `<th>${t.label}</th>`);
    html += `</tr></thead><tbody>`;

    // ROWS
    tanks.forEach(tank => {

        html += `<tr><td>${tank.name}</td>`;

        times.forEach(time => {

            // 🔥 Priority: USER OVERRIDE > SOP
            let display = get_override_display(frm, tank.name, time.value);
            if (!display) {
                display = get_sop_display(sop_data, tank.stage, time.value);
            }

            html += `
                <td>
                    <input type="text"
                        class="feed-input"
                        data-tank="${tank.name}"
                        data-time="${time.value}"
                        value="${display || ''}"
                        style="width:90px; text-align:center; border:none; outline:none; background:transparent;">
                </td>
            `;
        });

        html += `</tr>`;
    });

    html += `</tbody></table>`;

    frm.fields_dict.feed_matrix_html.$wrapper.html(html);

    bind_events(frm);
}


async function get_sop_data() {
    return await frappe.db.get_list('Feed SOP Master', {
        fields: ['stage', 'time', 'food_type', 'qty', 'shift'],
        limit: 10000
    });
}


function get_sop_display(sop_data, stage, time) {

    if (!stage) return "";

    let rows = sop_data.filter(s => {
    
        if (s.stage !== stage) return false;
    
        let sop_hour = parseInt(s.time);
        if (sop_hour !== time) return false;
    
        // 🔥 SHIFT LOGIC HERE
        if (frm.doc.shift_type === "Day Shift") {
            return sop_hour >= 6 && sop_hour < 18;
        } else {
            return (sop_hour >= 18 || sop_hour < 6);
        }
    });

    if (!rows.length) return "";

    return rows.map(r =>
        `${abbr(r.food_type)}:${r.qty}`
    ).join(" | ");
}


// 🔍 USER OVERRIDE → display
function get_override_display(frm, tank, time) {

    let rows = (frm.doc.feed_matrix || []).filter(r =>
        r.tank === tank && r.time == time
    );

    if (!rows.length) return "";

    return rows.map(r =>
        `${abbr(r.food_type)}:${r.qty}`
    ).join(" | ");
}


// 💾 SAVE OVERRIDES
function bind_events(frm) {

    frm.fields_dict.feed_matrix_html.$wrapper
        .find(".feed-input")

        // allow only numbers, letters, :, |
        .on("input", function () {
            let v = $(this).val();
            v = v.replace(/[^0-9a-zA-Z:|.\s]/g, '');
            $(this).val(v);
        })

        .on("change", function () {

            let tank = $(this).data("tank");
            let time = $(this).data("time");
            let text = $(this).val();  // e.g. "A:250 | R:1"

            // remove existing overrides for this cell
            frm.doc.feed_matrix = (frm.doc.feed_matrix || []).filter(r =>
                !(r.tank === tank && r.time == time)
            );

            if (!text) {
                frm.refresh_field("feed_matrix");
                return;
            }

            // parse "A:250 | R:1"
            let parts = text.split("|");

            parts.forEach(p => {
                let [food_abbr, qty] = p.split(":").map(s => s.trim());
                if (!qty) return;

                let row = frm.add_child("feed_matrix");
                row.tank = tank;
                row.time = time;
                row.food_type = food_abbr; // store abbr/text
                // row.qty = flt(qty);
                row.qty = isNaN(qty) ? 0 : parseFloat(qty);
            });

            frm.refresh_field("feed_matrix");
        });
}


// ⏰ SHIFT TIMES
function get_shift_times(shift) {
    let times = [];

    if (shift === "Day Shift") {
        for (let i = 6; i < 18; i++) {
            times.push({ value: i, label: format_time(i) });
        }
    } else {
        for (let i = 18; i < 24; i++) {
            times.push({ value: i, label: format_time(i) });
        }
        for (let i = 0; i < 6; i++) {
            times.push({ value: i, label: format_time(i) });
        }
    }
    return times;
}


// 🕐 FORMAT
function format_time(hour) {
    let suffix = hour >= 12 ? "PM" : "AM";
    let h = hour % 12 || 12;
    return `${h}${suffix}`;
}


// 🔤 small abbreviation helper (A, Ar, P…)
function abbr(name) {
    if (!name) return "";
    let parts = name.split(" ");
    if (parts.length === 1) return parts[0].substring(0, 1).toUpperCase();
    return parts.map(p => p[0].toUpperCase()).join("");
}





