frappe.ui.form.on('Tank Health Log', {

    sample_volume(frm) {
        calculate_population(frm);
    },

    shrimp_count_in_sample(frm) {
        calculate_population(frm);
    },

    tank_water_volume(frm) {
        calculate_population(frm);
    }

});

function calculate_population(frm) {

    if (frm.doc.sample_volume && 
        frm.doc.shrimp_count_in_sample && 
        frm.doc.tank_water_volume) {

        let density = frm.doc.shrimp_count_in_sample / frm.doc.sample_volume;
        let estimated = density * frm.doc.tank_water_volume;

        frm.set_value("estimated_live_count", Math.round(estimated));
    }
}

