        calculate_recirculation_time(frm);
    },

    pump_start_time: function(frm) {
        calculate_pump_runtime(frm);
    },

    pump_stop_time: function(frm) {
        calculate_pump_runtime(frm);
    },

    circulation_start_time: function(frm) {
        calculate_recirculation_time(frm);
    },

    circulation_end_time: function(frm) {
        calculate_recirculation_time(frm);
    }

});


// ==============================
// TOTAL INTAKE VOLUME
// ==============================

const calculate_total_intake = (frm) => {

    let total = 0;

    (frm.doc.intake_rows || []).forEach(row => {
        total += row.volume || 0;
    });

    frm.set_value("total_intake_volume", total);

};


// ==============================
// PUMP RUNTIME (Midnight Safe)
// ==============================

const calculate_pump_runtime = (frm) => {

    if (
        frm.doc.date &&
        frm.doc.to_date &&
        frm.doc.pump_start_time &&
        frm.doc.pump_stop_time
    ) {

        let start_datetime = moment(
            frm.doc.date + " " + frm.doc.pump_start_time
        );

        let end_datetime = moment(
            frm.doc.to_date + " " + frm.doc.pump_stop_time
        );

        let total_minutes = end_datetime.diff(start_datetime, "minutes");

        if (total_minutes < 0) {
            frappe.msgprint("Pump Stop Date & Time must be after Pump Start Date & Time");
            frm.set_value("pump_runtime", "");
            return;
        }

        let hours = Math.floor(total_minutes / 60);
        let minutes = total_minutes % 60;

        frm.set_value("pump_runtime", hours + " hr " + minutes + " min");

    }

};


// ==============================
// RECIRCULATION TIME (Midnight Safe)
// ==============================

const calculate_recirculation_time = (frm) => {

    if (
        frm.doc.date &&
        frm.doc.to_date &&
        frm.doc.circulation_start_time &&
        frm.doc.circulation_end_time
    ) {

        let start_datetime = moment(
            frm.doc.date + " " + frm.doc.circulation_start_time
        );

        let end_datetime = moment(
            frm.doc.to_date + " " + frm.doc.circulation_end_time
        );

        let total_minutes = end_datetime.diff(start_datetime, "minutes");

        if (total_minutes < 0) {
            frappe.msgprint("Circulation Stop Date & Time must be after Circulation Start Date & Time");
            frm.set_value("recirculation_time", "");
            return;
        }

        let hours = Math.floor(total_minutes / 60);
        let minutes = total_minutes % 60;

        frm.set_value("recirculation_time", hours + " hr " + minutes + " min");

    }

};

