function set_reservoir_query(frm) {

    frm.set_query("reservoir", function() {

        // 🔵 DAILY CHECK
        if (frm.doc.activity_type === "Daily Check") {
            return {
                filters: {
                    tank_type: ["!=", "Collection Reservoir"]
                }
            };
        }

        // 🟢 TREATMENT
        if (frm.doc.activity_type === "Treatment" && frm.doc.treatment_type) {
            if (frm.doc.treatment_type === "De-Ozonation") {
                return {
                    filters: {
                        tank_type: "Ozonation"
                    }
                };
            }
            if (frm.doc.treatment_type === "Chlorination") {
                return {
                    filters: [
                        ["tank_type", "not in", ["De-chlorination", "Ozonation",""]]
                    ]
                };
            }
            if (frm.doc.treatment_type === "ETDA") {
                return {
                    filters: {
                        tank_type: ["!=", "Collection Reservoir"]
                    }
                };
            }
            return {
                filters: {
                    tank_type: frm.doc.treatment_type
                }
            };
        }

        // 🟣 FINAL TRANSFER → only Ozonation reservoirs
        if (frm.doc.activity_type === "Final Transfer to Tank") {
            return {
                filters: {
                    tank_type: "Ozonation"
                }
            };
        }

        return {};
    });

}




