function apply_transfer_filters(frm) {

    // 🔵 FROM RESERVOIR
    frm.set_query("from_reservoir", "transfers", function() {

        if (frm.doc.cr_to_reservoir) {
            // Only Collection Reservoir
            return {
                filters: {
                    tank_type: "Collection Reservoir"
                }
            };
        }

        if (frm.doc.reservoir_to_reservoir) {
            // Exclude Collection Reservoir
            return {
                filters: {
                    tank_type: ["!=", "Collection Reservoir"]
                }
            };
        }

        return {};
    });


    // 🟢 TO RESERVOIR
    frm.set_query("to_reservoir", "transfers", function() {

        if (frm.doc.cr_to_reservoir || frm.doc.reservoir_to_reservoir) {
            // Always exclude Collection Reservoir
            return {
                filters: {
                    tank_type: ["!=", "Collection Reservoir"]
                }
            };
        }

        return {};
    });

}

