    setup(frm) {
        frm.set_query("tank_no", "tank_quantities", function(doc) {

            if (!doc.shed) {
                return {};
            }

            return {
                filters: [
                    ["Hatchery Tank", "shed", "=", doc.shed],
                    ["Hatchery Tank", "status", "=", "Active"],
                    ["Hatchery Tank", "current_water_level", ">", 0]
                ]
            };
        });
    },

    shrimp_batch(frm) {

        if (!frm.doc.shrimp_batch) {
            frm.set_df_property("shed", "options", "");
            frm.set_value("shed", "");
            return;
        }

        frappe.db.get_doc("Shrimp Batch", frm.doc.shrimp_batch)
            .then(batch => {

                let shed_options = [];

                if (batch.tankwise_quantity) {
                    batch.tankwise_quantity.forEach(row => {

                        // ✅ ONLY Shrimp Production sheds
                        if (row.shed && row.purpose === "Shrimp Production") {
                            shed_options.push(row.shed);
                        }
                    });
                }

                // Remove duplicates
                shed_options = [...new Set(shed_options)];

                let options_string = shed_options.join("\n");

                frm.set_df_property("shed", "options", options_string);

                if (frm.doc.shed && !shed_options.includes(frm.doc.shed)) {
                    frm.set_value("shed", "");
                }
            });
    },

    shed(frm) {
        frm.clear_table("tank_quantities");
        frm.refresh_field("tank_quantities");
