function apply_transfer_filters(frm) {

    // -------------------------------
    // Reservoir Pumping
    // CR → R1,R2,R3
    // -------------------------------
    if (frm.doc.transfer_type === "Reservoir Pumping") {

        frm.set_query("from_reservoir", "transfer_rows", function() {
            return {
                filters: {
                    name: ["in", ["CR1", "CR2","Fresh Water Reservoir"]]
                }
            };
        });

        frm.set_query("to_reservoir", "transfer_rows", function() {
            return {
                filters: {
                    name: ["in", ["R1", "R2", "R3"]]
                }
            };
        });
    }

    // -------------------------------
    // For De-chlorination
    // R1,R2,R3 → R6,R7,R8,R9
    // -------------------------------
    else if (frm.doc.transfer_type === "For De-chlorination") {

        frm.set_query("from_reservoir", "transfer_rows", function() {
            return {
                filters: {
                    name: ["in", ["R1", "R2", "R3"]]
                }
            };
        });

        frm.set_query("to_reservoir", "transfer_rows", function() {
            return {
                filters: {
                    name: ["in", ["R6", "R7", "R8", "R9"]]
                }
            };
        });
    }

    // -------------------------------
    // For Ozonation
    // R6,R7,R8,R9 → R4,R5
    // -------------------------------
    else if (frm.doc.transfer_type === "For Ozonation") {

        frm.set_query("from_reservoir", "transfer_rows", function() {
            return {
                filters: {
                    name: ["in", ["R6", "R7", "R8", "R9"]]
                }
            };
        });

        frm.set_query("to_reservoir", "transfer_rows", function() {
            return {
                filters: {
                    name: ["in", ["R4", "R5"]]
                }
            };
        });
    }

}

