        calculate_row(frm, cdt, cdn);
    },

    chemicals_used_add(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    }
});




function calculate_all_rows(frm) {

    if (frm.doc.activity_type !== "Treatment") return;
    if (frm.doc.treatment_type !== "Chlorination") return;
    if (!frm.doc.check_volume) return;

    frm.doc.chemicals_used.forEach(row => {
        calculate_single(frm, row);
    });

    frm.refresh_field("chemicals_used");
}


function calculate_row(frm, cdt, cdn) {

    if (frm.doc.activity_type !== "Treatment") return;
    if (frm.doc.treatment_type !== "Chlorination") return;

    let row = locals[cdt][cdn];
    calculate_single(frm, row);
}


function calculate_single(frm, row) {

    if (!frm.doc.check_volume) return;
    if (!row.concentration) return;
    if (!row.ppm) return;

    let volume = flt(frm.doc.check_volume);       // Tons
    let concentration = flt(row.concentration);   // %
    let ppm = flt(row.ppm);                       // Desired ppm

    if (concentration <= 0 || ppm <= 0) return;

    // Final Formula
    let required_qty = (volume * ppm) / (concentration / 100);

    row.quantity = flt(required_qty, 2);  // 2 decimals only
}



