frappe.ui.form.on("Algae Production Batch", {

    onload: function(frm) {

        // Build rows only first time
        if (
            frm.doc.initial_stage &&
            (
                !frm.doc.stage_details ||
                frm.doc.stage_details.length === 0
            )
        ) {
            build_stage_table(frm);
        }
    },

    initial_stage: function(frm) {

        if (!frm.doc.initial_stage) return;

        // Prevent accidental data loss
        if (
            (frm.doc.stage_details && frm.doc.stage_details.length > 0) ||
            (frm.doc.table_iugc && frm.doc.table_iugc.length > 0)
        ) {

            frappe.confirm(
                "Changing Initial Stage will reset all existing stage rows. Continue?",
                function () {
                    build_stage_table(frm);
                },
                function () {
                    // optional cancel action
                }
            );

        } else {

            build_stage_table(frm);

        }
    }

});


function build_stage_table(frm) {

    if (!frm.doc.initial_stage) return;

    const stages = [
        "Test Tube",
        "100ml Starter",
        "Conical Flask",
        "2L Flask",
        "18 Liter Carboy",
        "FRB",
        "Cement Tank"
    ];

    const uoms = {
        "Test Tube": "ml",
        "100ml Starter": "ml",
        "Conical Flask": "ml",
        "2L Flask": "Ltrs",
        "18 Liter Carboy": "Ltrs",
        "FRB": "Ltrs",
        "Cement Tank": "Ton"
    };

    const start_index = stages.indexOf(frm.doc.initial_stage);

    if (start_index === -1) {
        frappe.msgprint("Invalid Initial Stage selected");
        return;
    }

    // Clear existing rows
    frm.clear_table("stage_details");
    frm.clear_table("table_iugc");

    // Stage Details Table
    for (let i = start_index; i < stages.length; i++) {

        let row = frm.add_child("stage_details");

        row.container_type = stages[i];
        row.uom = uoms[stages[i]];

    }

    // IUGC Table
    for (let i = start_index; i < stages.length; i++) {

        let row = frm.add_child("table_iugc");

        row.container_type = stages[i];

    }

    // Refresh tables
    frm.refresh_field("stage_details");
    frm.refresh_field("table_iugc");

}

