function set_stage_dates(frm) {

    if (!frm.doc.date) return;

    let start_date = frappe.datetime.str_to_obj(frm.doc.date);

    (frm.doc.stage_details || []).forEach(function(row, index) {

        // Each stage +2 days
        let new_date = frappe.datetime.add_days(start_date, index * 2);

        frappe.model.set_value(
            row.doctype,
            row.name,
            "date",
            frappe.datetime.obj_to_str(new_date)
        );

    });

    // Set Expected Harvest Date = Last Row Date
    if (frm.doc.stage_details.length > 0) {

        let last_row = frm.doc.stage_details[frm.doc.stage_details.length - 1];

        let harvest_date = frappe.datetime.add_days(start_date, (frm.doc.stage_details.length - 1) * 2);

        frm.set_value("expected_harvest_date", harvest_date);
    }

}







