frappe.ui.form.on('Quotation', {
    refresh: function(frm) {

        // Only show if saved
        if (frm.is_new()) return;

        // WhatsApp SVG Icon
        let wa_svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 448 512" style="width:16px;height:16px;fill:white;"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-32.6-16.3-54-29.1-75.5-66-5.7-9.8 5.7-9.1 16.3-30.3 1.8-3.7 .9-6.9-.5-9.7-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 35.2 15.2 49 16.5 66.6 13.9 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"/></svg>`;

        let button_content = `<span style="display:flex;align-items:center;gap:6px;">${wa_svg} Share on WhatsApp</span>`;

        let wa_btn = frm.page.add_inner_button(button_content, function() {

            let mobile = frm.doc.custom_customer_mobile_no;
            let customer = frm.doc.customer_name;
            let company = frm.doc.custom_company_name || "Deenaj Shrimp Hatcheries";
            let total = frm.doc.grand_total;
            let doc_name = frm.doc.name;
            let order_date = frm.doc.transaction_date || "";
            
            if (!mobile) {
                frappe.msgprint({
                    title: __('Missing Information'),
                    indicator: 'orange',
                    message: __('Please enter the Customer Mobile No.')
                });
                return;
            }

            frappe.call({
                method: "generate_quotation_pdf",
                args: { name: doc_name },
                freeze: true,
                freeze_message: __("Generating PDF..."),
                callback: function(r) {

                    if (r.message && r.message.status === "success") {

                        let pdf_link = window.location.origin + r.message.file_url;

                        // Build Items Section
                        let items_text = "";
                        frm.doc.items.forEach((item, i) => {
                            items_text += `
${i+1}. ${item.item_name}
  Qty: ${item.qty}
  Rate: ${item.rate}
  Salinity: ${item.custom_salinity || ""}
  PL Stage: ${item.custom_pl_stage || ""}
  Delivery: ${item.custom_delivery_date || ""}`;
                        });

                        // Final WhatsApp Message
                        let message = `Hello ${customer} garu,

${company}

━━━━━━━━━━━━━━━
*Customer Details*
━━━━━━━━━━━━━━━
Name: ${customer}
Mobile: ${mobile}

━━━━━━━━━━━━━━━
*Order Details*
━━━━━━━━━━━━━━━
No: ${doc_name}
Order Date: ${order_date}

${items_text}

Total: ₹${total}

Download Quotation:
${pdf_link}

Please let us know if any changes are required.

Thank you,
*${company}*`;

                        let phone = mobile.replace(/\D/g, '');
                        if (!phone.startsWith('91') && phone.length <= 10) {
                            phone = '91' + phone;
                        }

                        window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`, '_blank');

                    } else {
                        frappe.msgprint({
                            title: __('Error'),
                            indicator: 'red',
                            message: __("Failed to generate PDF.")
                        });
                    }
                }
            });

        });

        // Button Styling
        wa_btn.removeClass('btn-default');

        let custom_style = 'background-color:#25D366 !important;color:white !important;font-weight:600 !important;border:none !important;border-radius:6px !important;padding:5px 12px !important;';
        let hover_style = 'background-color:#1DA851 !important;color:white !important;font-weight:600 !important;border:none !important;border-radius:6px !important;padding:5px 12px !important;';

        wa_btn.attr('style', custom_style);

        wa_btn.on('mouseenter', function() {
            $(this).attr('style', hover_style);
        });

        wa_btn.on('mouseleave', function() {
            $(this).attr('style', custom_style);
        });
    }
});

