function set_latest_shrimp_batch(frm) {

    if (!frm.is_new()) return; // only for new docs

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Shrimp Batch",
            fields: ["name"],
            order_by: "creation desc",
            limit_page_length: 1
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                frm.set_value("shrimp_batch", r.message[0].name);
            }
        }
    });

}

frappe.ui.form.on("Feed Scheduling Entry", {

    setup(frm) {

        // Filter Tank Stocking Batch link field
        frm.set_query("tank_stocking_batch", function () {
            return {
                filters: {
                    shrimp_batch: frm.doc.shrimp_batch,
                    shed: frm.doc.shed
                }
            };
        });

    },

    shrimp_batch(frm) {

        if (!frm.doc.shrimp_batch) {
            frm.set_df_property("shed", "options", "");
            return;
        }

        // Get sheds from Tank Stocking
        frappe.db.get_list("Tank Stocking", {
            filters: {
                shrimp_batch: frm.doc.shrimp_batch
            },
            fields: ["shed"]
        }).then(records => {

            let sheds = records.map(r => r.shed);
            sheds = [...new Set(sheds)];

            frm.set_df_property("shed", "options", sheds.join("\n"));

        });

    },

    tank_stocking_batch(frm) {

        if (!frm.doc.tank_stocking_batch) return;

        frappe.db.get_doc("Tank Stocking", frm.doc.tank_stocking_batch)
        .then(doc => {

            frm.clear_table("tank_feed_details");

            (doc.tank_quantities || []).forEach(row => {

                let child = frm.add_child("tank_feed_details");

                child.tank = row.tank_no;
                child.current_stage = doc.status;

            });

            frm.refresh_field("tank_feed_details");

        });

    }

});




