frappe.ui.form.on("Tank Health Log", {

    onload(frm) {
        set_latest_shrimp_batch(frm);
    },

    setup(frm) {

        // Filter Tank Stocking based on Shrimp Batch + Shed
        frm.set_query("tank_stocking", function () {

            if (!frm.doc.shrimp_batch || !frm.doc.shed) {
                return {};
            }

            return {
                filters: {
                    shrimp_batch: frm.doc.shrimp_batch,
                    shed: frm.doc.shed
                }
            };
        });

    },

    // Load Shed options based on Shrimp Batch
    shrimp_batch(frm) {

        if (!frm.doc.shrimp_batch) {
            frm.set_df_property("shed", "options", "");
            return;
        }

        frappe.db.get_list("Tank Stocking", {
            filters: {
                shrimp_batch: frm.doc.shrimp_batch
            },
            fields: ["shed"]
        }).then(records => {

            let sheds = records.map(r => r.shed);
            sheds = [...new Set(sheds)];

            frm.set_df_property("shed", "options", sheds.join("\n"));

        });

    },

    // Clear dependent fields when shed changes
    shed(frm) {
        frm.set_value("tank_stocking", "");
        frm.set_value("tank", "");
    },

    // When Tank Stocking is selected → load tanks
    tank_stocking(frm) {

        if (!frm.doc.tank_stocking) return;

        frappe.db.get_doc("Tank Stocking", frm.doc.tank_stocking)
        .then(doc => {

            let tanks = [];

            (doc.tank_quantities || []).forEach(row => {
                if (row.tank_no) {
                    tanks.push(row.tank_no);
                }
            });

            tanks = [...new Set(tanks)];

            // Filter Tank field
            frm.set_query("tank", function() {
                return {
                    filters: [
                        ["Hatchery Tank", "name", "in", tanks]
                    ]
                };
            });

        });

    }

});


function set_latest_shrimp_batch(frm) {

    if (!frm.is_new()) return;

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Shrimp Batch",
            fields: ["name"],
            order_by: "creation desc",
            limit_page_length: 1
        },
        callback: function(r) {

            if (r.message && r.message.length > 0) {

                frm.set_value("shrimp_batch", r.message[0].name);

                // trigger shed loading automatically
                frm.trigger("shrimp_batch");

            }

        }
    });

}




