frappe.ui.form.on("Tank Health Log", {

    current_stage(frm){

        frm.clear_table("micro_checks");

        let stage = frm.doc.current_stage || "";

        let rows = [];

        if(stage.startsWith("N")){
            rows = [
                "Setae deformity",
                "Stage uniformity",
                "Lipid droplets",
                "Relative size",
                "Vibrio count"
            ];
        }

        if(stage.startsWith("Z")){
            rows = [
                "Setae deformity",
                "Stage uniformity",
                "Gut fullness",
                "Chromatophore",
                "Necrosis",
                "Vibrio count"
            ];
        }

        if(stage.startsWith("M")){
            rows = [
                "Abdomen deformity",
                "Setae deformity",
                "Stage uniformity",
                "Gut fullness",
                "Chromatophore",
                "Necrosis"
            ];
        }

        rows.forEach(p=>{
            let r = frm.add_child("micro_checks");
            r.parameter = p;
        });

        frm.refresh_field("micro_checks");

    }

});


frappe.ui.form.on("Tank Micro Check", {

    observation(frm,cdt,cdn){

        let row = locals[cdt][cdn];

        if(row.observation >= 80){
            row.rating = "Good";
            row.score = 2;
        }
        else if(row.observation >= 50){
            row.rating = "Fair";
            row.score = 1;
        }
        else{
            row.rating = "Poor";
            row.score = 0;
        }

        frm.refresh_field("micro_checks");

    }

});

frappe.ui.form.on("Reservoir Log", {

    shed: function(frm) {

        if (!frm.doc.shed) return;

        frm.clear_table("tank_transfers");

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Hatchery Tank",
                fields: ["name", "shed", "current_water_level"],
                limit_page_length: 100,
                order_by: "name asc"
            },
            callback: function(r) {

                if (r.message) {

                    r.message.forEach(function(tank) {

                        if (tank.shed === frm.doc.shed) {

                            let row = frm.add_child("tank_transfers");

                            row.tank = tank.name;
                            row.shed = tank.shed;
                            row.available_volume = tank.current_water_level || 0;

                        }

                    });

                    frm.refresh_field("tank_transfers");

                }

            }
        });

    }

});

frappe.ui.form.on("Tank Stocking", {

    before_submit(frm) {

        let errors = [];

        frm.doc.tank_quantities.forEach(function(row) {

            if ((row.water_level || 0) <= 0) {
                errors.push("Row " + row.idx + " - " + row.tank_no);
            }

        });

        if (errors.length > 0) {

            frappe.throw(
                "No sufficient water in the tank:<br><b>" +
                errors.join("<br>") +
                "</b>"
            );

        }

    }

});

frappe.ui.form.on("Tank Health Log", {

    current_stage: function(frm) {

        if(!frm.doc.current_stage) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Check Parameters",
                filters: {
                    stage: frm.doc.current_stage
                },
                fields: ["parameter"]
            },
            callback: function(r){

                frm.clear_table("micro_checks");

                let i = 1;

                r.message.forEach(function(row){

                    let child = frm.add_child("micro_checks");

                    child.no = i;
                    child.parameter = row.parameter;

                    i++;

                });

                frm.refresh_field("micro_checks");

            }
        });

    }

});

