function color_field(frm, fieldname, status){

    let field = frm.fields_dict[fieldname].$wrapper.find('input');

    if(!field) return;

    if(status === "good"){

        field.css({
            "border":"2px solid #28a745",
            "background":"#e9f7ef"
        });

    }
    else if(status === "fair"){

        field.css({
            "border":"2px solid #fd7e14",
            "background":"#fff3e6"
        });

    }
    else{

        field.css({
            "border":"2px solid #dc3545",
            "background":"#fdecea"
        });

    }

}

