// ================= RULE ENGINE =================

const PL_RULES = {

    larval_behavior: { type:"select", good:["Active"], fair:["Intermediate"], poor:["Slow"] },
    hp_colour: { type:"select", good:["Dark"], fair:["Pale"], poor:["Transparent"] },
    hp_lipid: { type:"select", good:["Good"], fair:["Moderate"], poor:["Less","Absent"] },
    hp_tubule_constrictions: { type:"select", good:["None"], fair:["Light"], poor:["Heavy"] },
    gut_content: { type:"select", good:["Full"], fair:["Moderate"], poor:["Empty"] },
    gill_development: { type:"select", good:["Complete"], fair:["Intermediate"], poor:["Slight"] },
    peristalsis: { type:"select", good:["High"], fair:["Moderate"], poor:["Absent"] },
    intestinal_peristalsis: { type:"select", good:["High"], fair:["Moderate"], poor:["Absent"] },
    chromatophore_colour: { type:"select", good:["Normal dark spots"], fair:["Pale / light"], poor:["No pigment"] },
    lipid_droplets: { type:"select", good:["Visible golden in HP"], fair:["Moderate"], poor:["Absent"] },
    chromatophore_stage: { type:"select", good:["Well Expanded"], fair:["Partially Expanded"], poor:["Absent"] },
    gut_fullness: { type:"select", good:["Full Dark"], fair:["Partially Dark"], poor:["Empty"] },
    luminescent_bacteria: { type:"select", good:["None"], fair:["Faint"], poor:["Glow"] },
    abdomen_deformity: { type:"select", good:["Straight/Normal"], fair:["Slight curve"], poor:["Bent"] },

    length: { type:"number", good:v=>v>10, fair:v=>v>=8, poor:v=>v<8 },
    stress_test: { type:"number", good:v=>v>90, fair:v=>v>=80, poor:v=>v<80 },
    size_variation: { type:"number", good:v=>v<15, fair:v=>v<=25, poor:v=>v>25 },
    muscle_gut_ratio: { type:"number", good:v=>v>80, fair:v=>v>=70, poor:v=>v<70 },
    deformity: { type:"number", good:v=>v<5, fair:v=>v<=10, poor:v=>v>10 },
    fouling: { type:"number", good:v=>v<5, fair:v=>v<=10, poor:v=>v>10 },
    necrosis: { type:"number", good:v=>v<5, fair:v=>v<=10, poor:v=>v>10 },
    muscle: { type:"number", good:v=>v<5, fair:v=>v<=10, poor:v=>v>10 },
    melanized_gills: { type:"number", good:v=>v<5, fair:v=>v<=10, poor:v=>v>10 },
    bolitas: { type:"number", good:v=>v===0, fair:v=>v<=3, poor:v=>v>3 },
    luminescence: { type:"number", good:v=>v<5, fair:v=>v<=10, poor:v=>v>10 },
    tank_mortality: { type:"number", good:v=>v<=2, fair:v=>v<=5, poor:v=>v>5 },
    survival_rate: { type:"number", good:v=>v>70, fair:v=>v>=40, poor:v=>v<40 },
    muscle_opaqueness: { type:"number", good:v=>v<5, fair:v=>v<=10, poor:v=>v>10 },
    // vibrio_count: { type:"number", good:v=v<1000, fair:v=>v<=10000, poor:v=v> 10000 }

};


// ================= APPLY RULE =================

function apply_rule(frm, field){

    let rule = PL_RULES[field];
    if(!rule) return;

    let value = frm.doc[field];
    if(value == null || value === "") return;

    let status = "";

    if(rule.type === "select"){

        if(rule.good.includes(value)) status = "good";
        else if(rule.fair.includes(value)) status = "fair";
        else status = "poor";

    } else {

        if(rule.good(value)) status = "good";
        else if(rule.fair(value)) status = "fair";
        else status = "poor";

    }

    color_field(frm, field, status);

}


// ================= APPLY ALL =================

function apply_all_pl_rules(frm){

    Object.keys(PL_RULES).forEach(field => {
        apply_rule(frm, field);
    });

}


// ================= COLOR FUNCTION (FIXED) =================

function color_field(frm, fieldname, status){

    let field = frm.fields_dict[fieldname]?.$wrapper;

    if(!field) return;

    let input = field.find('input, select');

    if(!input.length) return;

    let styles = {
        good: {
            border: "2px solid #28a745",
            background: "#e9f7ef"
        },
        fair: {
            border: "2px solid #fd7e14",
            background: "#fff3e6"
        },
        poor: {
            border: "2px solid #dc3545",
            background: "#fdecea"
        }
    };

    let s = styles[status];

    input.attr("style",
        `border:${s.border} !important;
         background:${s.background} !important;`
    );

}

