frappe.ui.form.on('Delivery Note Item', {

    custom_no_of_packets: function(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    custom_per_packet: function(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    items_remove: function(frm) {
        calculate_total(frm);
    }
});

function calculate_row(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    let gross = Math.round((row.custom_no_of_packets || 0) * (row.custom_per_packet || 0));

    if (row.custom_gross_quantity !== gross) {
        frappe.model.set_value(cdt, cdn, 'custom_gross_quantity', gross);
    }

    calculate_total(frm);
}

function calculate_total(frm) {
    let total = 0;

    (frm.doc.items || []).forEach(function(row) {
        total += row.custom_gross_quantity || 0;
    });

    total = Math.round(total);

    if (frm.doc.custom_gross_quantity !== total) {
        frm.set_value('custom_gross_quantity', total);
    }

    calculate_bonus(frm);
}

function calculate_bonus(frm) {
    let total_qty = frm.doc.total_qty || 0;
    let gross = frm.doc.custom_gross_quantity || 0;

    let bonus = Math.round(gross - total_qty);

    if (frm.doc.custom_bonus_quantity !== bonus) {
        frm.set_value('custom_bonus_quantity', bonus);
    }
}

// ----------------------
// INITIAL LOAD
// ----------------------
function calculate_all(frm) {
    calculate_total(frm);
    calculate_bonus(frm);
}

