function transfer_stage(frm) {

    let stages = [
        "50 mL",
        "250 mL",
        "2 L",
        "18 L",
        "40 L FRP",
        "8T Cement Tank"
    ];

    let current = frm.doc.current_stage || "50 mL";
    let next = stages[stages.indexOf(current) + 1];

    if (!next) {
        frappe.msgprint("🎉 Final Stage Reached");
        return;
    }
    
    frappe.call({
        method: "frappe.client.insert",
        args: {
            doc: {
                doctype: "Transfer Entry",
                batch: frm.doc.name,
                transfer_date: frappe.datetime.get_today(),
                from_stage: current,
                to_stage: next
            }
        },
        callback: function() {

            frappe.call({
                method: "frappe.client.set_value",
                args: {
                    doctype: "Algae Batch",
                    name: frm.doc.name,
                    fieldname: {
                        current_stage: next,
                        stage_start_date: frappe.datetime.get_today(),
                        expected_shift_date: frappe.datetime.add_days(frappe.datetime.get_today(), 2),
                        status: next === "8T Cement Tank" ? "Production Ready" : "Growing"
                    }
                },
                callback: function() {
                    frappe.msgprint("✅ Transferred Successfully");
                    frm.reload_doc();
                }
            });

        }
    });
}

