// LOAD STAGE INVENTORY
// -------------------------------
function load_stage_inventory(frm) {

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Stage Inventory",
            fields: ["name", "units", "stage_order"],
            order_by: "stage_order asc",
            limit_page_length: 100
        },
        callback: function(r) {

            if (!r.message) return;

            frm.clear_table("transfer_details");

            r.message.forEach((stage, index) => {

                // ❌ Skip last stage (no next stage)
                if (!r.message[index + 1]) {
                    return;
                }

                let row = frm.add_child("transfer_details");

                row.current_stage = stage.name;
                row.available_units = stage.units || 0;
                row.next_stage = r.message[index + 1].name;
                row.transfer_units = 0;
            });

            frm.refresh_field("transfer_details");
        }
    });
}


