frappe.ui.form.on("Water Request", {

    refresh(frm) {
        frm.add_custom_button(__("Sea Water Salinity"), function () {
            frappe.set_route("Form", "Sea Water Salinity", "Sea Water Salinity");
        });
    },

    shed(frm) {

        if (!frm.doc.shed) {
            frm.clear_table("table_motw");
            frm.refresh_field("table_motw");
            return;
        }

        frappe.db.get_list("Hatchery Tank", {
            filters: {
                shed: frm.doc.shed,
                status: "Active"
            },
            fields: [
                "name",
                "current_stage",
                "current_water_level",
                "current_salinity"
            ],
            limit: 1000

        }).then(records => {

            records = records || [];

            if (frm.doc.shed === "ALGAE SECTION") {

                // Ascending
                records.sort((a, b) => {
                    return parseInt(a.name.replace(/\D/g, "")) -
                           parseInt(b.name.replace(/\D/g, ""));
                });

            } else {

                // Descending
                records.sort((a, b) => {
                    return parseInt(b.name.replace(/\D/g, "")) -
                           parseInt(a.name.replace(/\D/g, ""));
                });

            }

            frm.clear_table("table_motw");

            records.forEach((tank, idx) => {

                let row = frm.add_child("table_motw");

                row.no = idx + 1;
                row.tank = tank.name;
                row.current_stage = tank.current_stage;
                row.current_volume = tank.current_water_level || 0;
                row.current_salinity = tank.current_salinity || 0;

                row.volume_up = 0;
                row.volume_down = 0;
                row.sea_water = 0;
                row.fresh_water = 0;

            });

            frm.refresh_field("table_motw");
            calculate_all_rows(frm);

        });

    }

});


