function calculate_all_rows(frm) {

    frappe.db.get_single_value(
        "Sea Water Salinity",
        "salinity"
    ).then(sea_salinity => {

        let SEA = flt(sea_salinity) || 35;

        (frm.doc.table_motw || []).forEach(row => {
            calculate_single_row(row, SEA);
        });

        frm.refresh_field("table_motw");
        calculate_totals(frm);

    });

}


function calculate_single_row(row, SEA) {

    let current_volume = flt(row.current_volume);
    let current_salinity = flt(row.current_salinity);
    let required_salinity = flt(row.required_salinity);

    // Volume after drain (remaining water)
    let remaining_volume = flt(row.volume_down);

    // Final desired water level (Raise Upto)
    let raise_upto = flt(row.volume_up);

    if (cur_frm.doc.shed === "ALGAE SECTION") {

        row.sea_water = flt(row.volume_up, 3);
        row.fresh_water = 0;

        return;
    }

    // Required fields
    if (!required_salinity || raise_upto <= 0) {
        row.sea_water = 0;
        row.fresh_water = 0;
        return;
    }

    // Validation
    if (remaining_volume > current_volume) {
        frappe.msgprint(__("Volume Down cannot be greater than Current Volume."));
        row.volume_down = current_volume;
        remaining_volume = current_volume;
    }

    // Raise Upto should be greater than or equal to remaining volume
    if (raise_upto < remaining_volume) {
        frappe.msgprint(__("Raise Upto cannot be less than Volume Down."));
        row.sea_water = 0;
        row.fresh_water = 0;
        return;
    }

    // Water drained (for reference)
    let drained_volume = current_volume - remaining_volume;

    // Water to be added
    let added_volume = raise_upto - remaining_volume;

    // Salt currently present
    let existing_salt = remaining_volume * current_salinity;

    // Salt required in final volume
    let required_salt = raise_upto * required_salinity;

    // Sea water required
    let sea = (required_salt - existing_salt) / SEA;

    // Fresh water required
    let fresh = added_volume - sea;

    // Validation
    if (sea < 0 || sea > added_volume || !isFinite(sea) || !isFinite(fresh)) {
        frappe.msgprint(__(
            "Required salinity cannot be achieved with the given values."
        ));

        row.sea_water = 0;
        row.fresh_water = 0;
        return;
    }

    row.sea_water = flt(sea, 3);
    row.fresh_water = flt(fresh, 3);
}

function calculate_totals(frm) {

    let total_sea = 0;
    let total_fresh = 0;

    (frm.doc.table_motw || []).forEach(row => {

        total_sea += flt(row.sea_water);
        total_fresh += flt(row.fresh_water);

    });

    frm.set_value("total_sea_water", flt(total_sea, 3));
    frm.set_value("total_fresh_water", flt(total_fresh, 3));

}





