function fetch_all_reservoirs(frm) {

    // IMPORTANT
    // Don't reload if already filled

    if (
        (frm.doc.cr_entry && frm.doc.cr_entry.length > 0) ||
        (frm.doc.chlorination_reservoirs_entry && frm.doc.chlorination_reservoirs_entry.length > 0) ||
        (frm.doc.dechlorination_entry && frm.doc.dechlorination_entry.length > 0) ||
        (frm.doc.ozonation_reservoirs_entry && frm.doc.ozonation_reservoirs_entry.length > 0)
    ) {
        return;
    }

    frappe.db.get_list("Reservoir", {
        filters: {
            reservoir_status: "Active"
        },
        fields: [
            "name",
            "tank_type",
            "current_volume"
        ],
        limit: 1000
    }).then(records => {
        
        // to make tank list order wise 
            records = records || [];

            records.sort((a, b) => {
            return parseInt(a.name.replace(/\D/g, "")) - parseInt(b.name.replace(/\D/g, ""));
            });

        records.forEach(res => {

            // =========================
            // COLLECTION RESERVOIR
            // =========================

            if (res.tank_type === "Collection Reservoir") {

                let row = frm.add_child("cr_entry");

                row.reservoir = res.name;
                row.previous_volume = res.current_volume || 0;
            }

            // =========================
            // CHLORINATION
            // =========================

            if (res.tank_type === "Chlorination") {

                let row = frm.add_child("chlorination_reservoirs_entry");

                row.reservoir = res.name;
                row.previous_volume = res.current_volume || 0;
            }

            // =========================
            // DE-CHLORINATION
            // =========================

            if (res.tank_type === "De-chlorination") {

                let row = frm.add_child("dechlorination_entry");

                row.reservoir = res.name;
                row.previous_volume = res.current_volume || 0;
            }

            // =========================
            // OZONATION
            // =========================

            if (res.tank_type === "Ozonation") {

                let row = frm.add_child("ozonation_reservoirs_entry");

                row.reservoir = res.name;
                row.previous_volume = res.current_volume || 0;
            }

        });

        frm.refresh_fields([
            "cr_entry",
            "chlorination_reservoirs_entry",
            "dechlorination_entry",
            "ozonation_reservoirs_entry"
        ]);

    });

}

