frappe.ui.form.on("CR Log Item", {

    concentration: function(frm, cdt, cdn) {
        calculate_cr_row(frm, cdt, cdn);
    },

    ppm: function(frm, cdt, cdn) {
        calculate_cr_row(frm, cdt, cdn);
    },

    current_volume: function(frm, cdt, cdn) {
        calculate_cr_row(frm, cdt, cdn);
    }

});


function calculate_cr_row(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    let volume = flt(row.current_volume);
    let concentration = flt(row.concentration);
    let ppm = flt(row.ppm);

    // Validation
    if (
        volume <= 0 ||
        concentration <= 0 ||
        ppm <= 0
    ) {

        frappe.model.set_value(cdt, cdn, "quantity", 0);

        return;
    }

    // Formula
    let required_qty = (volume * ppm) / (concentration / 100);

    frappe.model.set_value(
        cdt,
        cdn,
        "quantity",
        flt(required_qty, 2)
    );

}

