function build_stage_table(frm){

    if(!frm.doc.initial_stage) return;

    let stages = [
        "Test Tube",
        "Conical Flask",
        "2L Flask",
        "18 Liter Carboy",
        "FRB",
        "Cement Tank"
    ];

    let uoms = {
        "Test Tube":"ml",
        "Conical Flask":"ml",
        "2L Flask":"Ltrs",
        "18 Liter Carboy":"Ltrs",
        "FRB":"Ltrs",
        "Cement Tank":"Ton"
    };

    let volumes = {
        "Test Tube":50,
        "Conical Flask":250,
        "2L Flask":2,
        "18 Liter Carboy":18,
        "FRB":500,
        "Cement Tank":1
    };

    frm.clear_table("table_cdub");

    let start_index = stages.indexOf(frm.doc.initial_stage);

    for(let i=start_index; i<stages.length; i++){

        let row = frm.add_child("table_cdub");

        row.container_type = stages[i];
        row.uom = uoms[stages[i]];
        row.per_unit_volume = volumes[stages[i]];

    }

    frm.refresh_field("table_cdub");

}

