function generate_schedule(frm) {
    frm.clear_table('items');

    let start = 6;   // 6 AM
    let end = 18;    // 6 PM

    for (let i = start; i <= end; i++) {
        let row = frm.add_child('items');

        let hour = i.toString().padStart(2, '0');
        row.time_slot = `${hour}:00:00`;
        row.status = "Pending";
    }

    frm.refresh_field('items');
}

