// ✅ CHECK REQUIRED FIELDS
function render_if_ready(frm) {
    if (frm.doc.shed && frm.doc.shift_type) {
        render_table(frm);
    } else {
        frm.fields_dict.feed_matrix_html.$wrapper.html("<p>Select Shed & Shift</p>");
    }
}


// 🚀 MAIN TABLE
async function render_table(frm) {

    let tanks = await frappe.db.get_list('Hatchery Tank', {
        filters: { shed: frm.doc.shed },
        fields: ['name']
    });

    if (!tanks.length) {
        frm.fields_dict.feed_matrix_html.$wrapper.html("<p>No tanks found</p>");
        return;
    }

    let times = get_shift_times(frm.doc.shift_type);

    let html = `<table class="table table-bordered text-center">`;

    // HEADER
    html += `<thead><tr><th>Tank</th>`;
    times.forEach(t => {
        html += `<th>${t.label}</th>`;
    });
    html += `</tr></thead><tbody>`;

    // ROWS
    tanks.forEach(tank => {

        html += `<tr><td>${tank.name}</td>`;

        times.forEach(time => {

            // 🔥 LOAD EXISTING VALUE
            let value = get_existing_value(frm, tank.name, time.value);

            html += `
                <td>
                    <input type="text"
                        class="feed-input"
                        data-tank="${tank.name}"
                        data-time="${time.value}"
                        value="${value || ''}"
                        style="width:60px; text-align:center; border:none; outline:none; background:transparent;">
                </td>
            `;
        });

        html += `</tr>`;
    });

    html += `</tbody></table>`;

    frm.fields_dict.feed_matrix_html.$wrapper.html(html);

    bind_events(frm);
}


// 🔍 GET SAVED VALUE
function get_existing_value(frm, tank, time) {

    let row = (frm.doc.feed_matrix || []).find(r =>
        r.tank === tank && r.time == time
    );

    return row ? row.qty : "";
}


// 💾 SAVE DATA
function bind_events(frm) {

    frm.fields_dict.feed_matrix_html.$wrapper
        .find(".feed-input")

        // Allow only numbers
        .on("input", function () {
            let value = $(this).val();
            value = value.replace(/[^0-9.]/g, '');
            $(this).val(value);
        })

        // Save to child table
        .on("change", function () {

            let tank = $(this).data("tank");
            let time = $(this).data("time");
            let qty = flt($(this).val());

            let row = (frm.doc.feed_matrix || []).find(r =>
                r.tank === tank && r.time == time
            );

            if (row) {
                frappe.model.set_value(row.doctype, row.name, "qty", qty);
            } else {
                let new_row = frm.add_child("feed_matrix");
                new_row.tank = tank;
                new_row.time = time;
                new_row.qty = qty;
            }

            frm.refresh_field("feed_matrix");
        });
}


// 🔥 SHIFT TIME LOGIC
function get_shift_times(shift) {

    let times = [];

    if (shift === "Day Shift") {
        for (let i = 6; i < 18; i++) {
            times.push({ value: i, label: format_time(i) });
        }
    }

    else if (shift === "Night Shift") {
        for (let i = 18; i < 24; i++) {
            times.push({ value: i, label: format_time(i) });
        }
        for (let i = 0; i < 6; i++) {
            times.push({ value: i, label: format_time(i) });
        }
    }

    return times;
}


// 🕐 FORMAT TIME
function format_time(hour) {
    let suffix = hour >= 12 ? "PM" : "AM";
    let h = hour % 12 || 12;
    return `${h}${suffix}`;
}





