            callback: function(r) {
                if (!r.message || r.message.length === 0) {
                    frappe.msgprint("No open advances found for this employee");
                    frm.refresh_field("expense_advance_item");
                    return;
                }

                r.message.forEach(adv => {
                    let row = frm.add_child("expense_advance_item");

                    row.advance_reference = adv.name;
                    row.date = adv.date;
                    row.advance_amount = adv.amount;

                    // Used = amount - balance
                    row.used_amount = adv.used_amount;

                    row.balance_amount = adv.balance_amount || 0;
                });

                frm.refresh_field("expense_advance_item");
            }
        });
    }
});

