function set_if_changed(frm, field, value) {
    if (frm.doc[field] !== value) {
        frm.set_value(field, value);
    }
}


function calculate_totals(frm) {

    // 🔹 1. Expenditure
    let total_expense = 0;
    (frm.doc.expense_entry_item || []).forEach(row => {
        total_expense += row.amount || 0;
    });

    set_if_changed(frm, 'expenditure', total_expense);


    // 🔹 2. Advance Amount
    let total_balance = 0;
    (frm.doc.expense_advance_item || []).forEach(row => {
        total_balance += row.balance_amount || 0;
    });

    set_if_changed(frm, 'advance_amount', total_balance);


    // 🔹 3. Remaining (no negative)
    let remaining = total_balance - total_expense;
    if (remaining < 0) remaining = 0;

    set_if_changed(frm, 'remaining_advance', remaining);


    // 🔹 4. Difference
    let difference = 0;
    if (total_expense > total_balance) {
        difference = total_expense - total_balance;
    }

    set_if_changed(frm, 'difference_amount', difference);


    // 🔹 5. FIFO Allocation
    let remaining_expense = total_expense;

    (frm.doc.expense_advance_item || []).forEach(row => {
        row.allocate_amount = 0;
    });

    (frm.doc.expense_advance_item || []).forEach(row => {

        if (remaining_expense <= 0) return;

        let available = row.balance_amount || 0;

        if (available > 0) {

            if (remaining_expense >= available) {
                row.allocate_amount = available;
                remaining_expense -= available;
            } else {
                row.allocate_amount = remaining_expense;
                remaining_expense = 0;
            }
        }
    });

    frm.refresh_field("expense_advance_item");
}

