function sync_row(frm) {

    if (!frm.doc.table_trzl || frm.doc.table_trzl.length === 0) {
        frm.add_child('table_trzl');
    }

    let row = frm.doc.table_trzl[0];

    row.qty = frm.doc.quantity || 0;
    row.rate = frm.doc.rate || 0;
    row.custom_pl_stage = frm.doc.pl_stage || '';
    row.custom_strain = frm.doc.line || '';
    row.custom_salinity = frm.doc.salinity || '';
    row.custom_delivery_date = frm.doc.delivery_date || '';

    row.amount = flt(row.qty) * flt(row.rate);

    frm.refresh_field('table_trzl');

    calculate_totals(frm);
}

