function get_shift_times(shift_type) {

    if (shift_type === "Night Shift") {

        return [
            "10PM",
            "11PM",
            "12AM",
            "1AM",
            "2AM",
            "3AM",
            "4AM",
            "5AM",
            "6AM",
            "7AM",
            "8AM",
            "9AM"
        ];
    }

    return [
        "10AM",
        "11AM",
        "12PM",
        "1PM",
        "2PM",
        "3PM",
        "4PM",
        "5PM",
        "6PM",
        "7PM",
        "8PM",
        "9PM"
    ];

}









