                    let cell_html = `+ Add Feed`;





                    if (existing.length > 0) {

                        cell_html = `
                        
                        `;
                        
                        cell_html += `<div class="feed-items">`;

                        existing.forEach(row => {

                            cell_html += `
                                <div class="feed-item">
                        
                                    <div class="feed-name">
                                        ${row.feed}
                                    </div>
                        
                                    <div class="feed-qty">
                                        ${row.planned_qty} ${row.uom || ""}
                                    </div>
                        
                                    ${
                                        row.feed === "ALGAE" && row.algae_tank
                                        ? `
                                            <div class="feed-tank">
                                                🟢 ${row.algae_tank}
                                            </div>
                                          `
                                        : ""
                                    }
                        
                                </div>
                            `;
                        
                        });
                        
                        cell_html += `</div>`;
                    
                    }
                    
                    
                    
                    

                    html += `

                        <td>

                            <div
                                class="feed-cell"
                                data-tank="${tank.name}"
                                data-stage="${tank.stage}"
                                data-time="${time}"
                            >

                                ${cell_html}

                            </div>

                        </td>

                    `;

                });





                html += `</tr>`;

            });





            html += `

                    </tbody>

                </table>

                </div>

            `;





            frm.fields_dict.feed_roster_html.$wrapper.html(html);

            bind_feed_events(frm);

        }

    });

}

function open_column_editor(frm, time) {

