function bind_column_editor(frm, d, rows) {

    // REMOVE BUTTON
    d.$wrapper.off("click", ".remove-feed");

    d.$wrapper.on("click", ".remove-feed", function () {

        let name = $(this).data("name");
    
        let row = rows.find(r => r.name === name);
    
        if (row) {
            row.__remove = true;
        }
    
        const card = $(this).closest(".editor-card");
    
        card.slideUp(150, function () {
            $(this).remove();
    
            // Optional message when nothing left
            if (d.$wrapper.find(".editor-card").length === 0) {
                d.$wrapper.find("#same-feed-editor").after(`
                    <div class="alert alert-warning text-center mt-3">
                        No feeds remaining for this time.
                    </div>
                `);
            }
        });
    
    });

    // APPLY SAME TO ALL
    d.$wrapper.off("change", "#same_for_all");

    d.$wrapper.on("change", "#same_for_all", function () {

        if ($(this).is(":checked")){
        
            d.$wrapper.find(".editor-card").hide();
        
            d.$wrapper.find("#same-feed-editor").show();
        
        }
        else{
        
            d.$wrapper.find(".editor-card").show();
        
            d.$wrapper.find("#same-feed-editor").hide();
        
        }

    });

}

function save_column_editor(frm, time, d, rows) {

    // Remove deleted rows
    frm.doc.feed_schedule_detail =
        frm.doc.feed_schedule_detail.filter(r => !r.__remove);

    let visible = rows.filter(r => !r.__remove);

    visible.forEach((row, i) => {

        row.feed =
            d.$wrapper.find(
            '.feed-input[data-name="'+row.name+'"]'
            ).val();

        row.planned_qty =
            d.$wrapper.find(
            '.qty-input[data-name="'+row.name+'"]'
            ).val();

        row.uom =
            d.$wrapper.find(
            '.uom-input[data-name="'+row.name+'"]'
            ).val();
            
    });

    // Apply Same Feed
    // Apply Same Feed
    // Apply Same Feed
    if (d.$wrapper.find("#same_for_all").is(":checked")) {
    
        let feed = d.$wrapper.find(".common-feed").val();
    
        let qty = d.$wrapper.find(".common-qty").val();
    
        let uom = d.$wrapper.find(".common-uom").val();
    
        visible.forEach(r => {
    
            r.feed = feed;
            r.planned_qty = qty;
            r.uom = uom;
    
        });
    
    }
    else {
    
        visible.forEach((row) => {
    
            row.feed =
                d.$wrapper.find('.feed-input[data-name="'+row.name+'"]').val();
    
            row.planned_qty =
                d.$wrapper.find('.qty-input[data-name="'+row.name+'"]').val();
    
            row.uom =
                d.$wrapper.find('.uom-input[data-name="'+row.name+'"]').val();
    
        });
    
    }

    frm.refresh_field("feed_schedule_detail");

    d.hide();

    render_feed_roster(frm);

    frappe.show_alert({
        message: "Updated Successfully",
        indicator: "green"
    });

}


function show_column_menu(frm, time, e) {

    $(".column-popup").remove();

    let popup = $(`
        <div class="column-popup">

            <div class="popup-item edit-option">
                <span class="fa fa-pencil"></span>
                Edit
            </div>

            <div class="popup-item delete-option">
                <span class="fa fa-trash"></span>
                Delete
            </div>

        </div>
    `);

    $("body").append(popup);

    const pos = $(e.currentTarget).offset();

    popup.css({
        top: pos.top + 20,
        left: pos.left - 65
    });

    popup.find(".edit-option").click(function () {

        popup.remove();

        open_column_editor(frm, time);

    });

    popup.find(".delete-option").click(function () {

        popup.remove();

        delete_column(frm, time);

    });

    $(document).one("click", function () {
        popup.remove();
    });

}



function bind_feed_events(frm) {

// ADD FEED
    
    $('.edit-cell').off().on('click',function(e){

        e.preventDefault();
        e.stopPropagation();
    
        let tank=$(this).data("tank");
        let time=$(this).data("time");
    
        open_edit_cell_dialog(frm,tank,time);
    
    });
    
    $(".column-menu").off().on("click", function (e) {
    
        e.preventDefault();
        e.stopPropagation();
    
        const time = $(this).data("time");
    
        show_column_menu(frm, time, e);
    
    });
    
    $('.delete-cell').off().on('click',function(e){

        e.preventDefault();
        e.stopPropagation();
    
        let tank=$(this).data("tank");
        let time=$(this).data("time");
    
        frm.doc.feed_schedule_detail=
            frm.doc.feed_schedule_detail.filter(d=>!(
    
                d.tank==tank &&
    
                d.feed_time==time
    
            ));
    
        frm.refresh_field("feed_schedule_detail");
    
        render_feed_roster(frm);
    
    });
    
    $('.feed-cell').off('click').on('click', function(event) {
    
        if (
            $(event.target).hasClass('edit-cell') ||
            $(event.target).hasClass('delete-cell')
        ) {
            return;
        }
    
        if (!frm.doc.feed_type) {
    
            frappe.msgprint("Please select Feed Type");
    
            return;
        }
    
        let tank = $(this).attr('data-tank');
        let stage = $(this).attr('data-stage');
        let time = $(this).attr('data-time');
    
        let dialog = new frappe.ui.Dialog({
    
            title: `${tank} - ${time}`,
    
            fields: [
    
                {
                    label:'Feed',
                    fieldname:'feed',
                    fieldtype:'Link',
                    options:'Item',
                    reqd:1,
                
                    onchange() {
                    
                        let feed = dialog.get_value("feed");
                    
                        if (!feed) return;
                    
                        // Show / Hide Algae Tank
                        if (feed == "ALGAE") {
                    
                            dialog.set_df_property("algae_tank","hidden",0);
                    
                        } else {
                    
                            dialog.set_df_property("algae_tank","hidden",1);
                            dialog.set_value("algae_tank","");
                    
                        }
                    
                        // Fetch UOM
                        frappe.db.get_value(
                            "Item",
                            feed,
                            "stock_uom"
                        ).then(r => {
                    
                            if (r.message) {
                                dialog.set_value("uom", r.message.stock_uom);
                            }
                    
                        });
                    
                    }
                },
    
                {
                    label:'Algae Tank',
                    fieldname:'algae_tank',
                    fieldtype:'Link',
                    options:'Hatchery Tank',
                
                    get_query() {
                        return {
                            filters:{
                                shed:'ALGAE SECTION'
                                // current_algae_volume:['>',0]
                            }
                        }
                    }
                },
    
                {
                    label:'Planned Qty',
                    fieldname:'planned_qty',
                    fieldtype:'Float',
                    reqd:1
                },
    
                {
                    label:'UOM',
                    fieldname:'uom',
                    fieldtype:'Link',
                    options:'UOM',
                    read_only:1
                }
    
            ],
    
            primary_action_label:'Add Feed',
    
            primary_action(values) {
    
                let exists = (frm.doc.feed_schedule_detail || []).find(d =>
    
                    d.tank === tank &&
                    d.feed_time === time &&
                    d.feed === values.feed
    
                );
    
                if (exists) {
    
                    frappe.msgprint("Feed already exists");
    
                    return;
                }
                
                console.log(values);
                frm.add_child('feed_schedule_detail', {
    
                    tank:tank,
                    stage:stage,
                    feed_time:time,
                    algae_tank: values.algae_tank,
                    feed:values.feed,
                    planned_qty:values.planned_qty,
                    uom:values.uom
    
                });
    
                frm.refresh_field('feed_schedule_detail');
    
                dialog.hide();
    
                setTimeout(() => {
    
                    render_feed_roster(frm);
    
                }, 100);
    
            }
    
        });
    
        dialog.show();
    
    
    
    
    
        // HIDE INITIALLY
    
        dialog.get_field('algae_tank').df.hidden = 1;
    
        dialog.refresh();
    
    
    
    });

}


function open_edit_cell_dialog(frm, tank, time) {

