function load_feed_board(frm) {

    if (!frm.doc.date || !frm.doc.shed || !frm.doc.shift_type) {
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Feed Schedule",
            filters: {
                schedule_date: frm.doc.date,
                shed: frm.doc.shed,
                shift_type: frm.doc.shift_type,
                docstatus: 1
            },
            fields: ["name"],
            limit_page_length: 1
        },
        callback(r) {

            if (!r.message.length) {

                frm.fields_dict.execution_board_html.$wrapper.html(`
                    <div style="
                        text-align:center;
                        padding:80px;
                        font-size:28px;
                        color:#888;
                    ">
                        No Feed Schedule Found
                    </div>
                `);

                return;
            }

            let schedule_name = r.message[0].name;

            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Feed Schedule",
                    name: schedule_name
                },
                callback(res) {

                    let doc = res.message;

                    let time_fields = [
                        "6pm","7pm","8pm","9pm","10pm","11pm",
                        "12am","1am","2am","3am","4am","5am"
                    ];

                    let html = `
                        <table class="table table-bordered">
                            <thead>
                                <tr>
                                    <th>Tank</th>
                    `;

                    time_fields.forEach(t => {
                        html += `<th>${t.toUpperCase()}</th>`;
                    });

                    html += `</tr></thead><tbody>`;

                    doc.feed_schedule_details.forEach(row => {

                        html += `<tr>`;

                        html += `
                            <td>
                                <b>${row.tank}</b>
                            </td>
                        `;

                        time_fields.forEach(field => {

                            let value = row[field];

                            if (value) {

                                html += `
                                    <td>
                                        <div class="feed-card" style="
                                            background:#f3f4f6;
                                            padding:15px;
                                            border-radius:12px;
                                            text-align:center;
                                        ">

                                            <b>${value}</b>

                                            <br><br>

                                            <button class="btn btn-success btn-sm done-btn">
                                                Done
                                            </button>

                                            <button class="btn btn-danger btn-sm skip-btn">
                                                Skip
                                            </button>

                                        </div>
                                    </td>
                                `;

                            } else {

                                html += `
                                    <td style="text-align:center;">
                                        -
                                    </td>
                                `;
                            }

                        });

                        html += `</tr>`;
                    });

                    html += `</tbody></table>`;

                    frm.fields_dict.execution_board_html.$wrapper.html(html);

                    bind_buttons(frm);
                }
            });
        }
    });
}


function bind_buttons(frm) {

    frm.fields_dict.execution_board_html.$wrapper.find(".done-btn")
        .click(function() {

            $(this).closest(".feed-card")
                .css("background", "#bbf7d0");

            frappe.show_alert({
                message: "Marked Done",
                indicator: "green"
            });
        });


    frm.fields_dict.execution_board_html.$wrapper.find(".skip-btn")
        .click(function() {

            $(this).closest(".feed-card")
                .css("background", "#fecaca");

            frappe.show_alert({
                message: "Marked Skipped",
                indicator: "red"
            });
        });
}

