function load_schedule(frm) {

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "Feed Schedule",

            filters: {
                schedule_date: frm.doc.date,
                shed: frm.doc.shed,
                shift_type: frm.doc.shift_type,
                docstatus: 1
            },

            fields: ["name"],

            limit_page_length: 500
        },

        callback: function(r) {

            if (!r.message || r.message.length === 0) {

                frm.fields_dict.execution_board_html.$wrapper.html(`
                    <div style="
                        padding:50px;
                        text-align:center;
                        font-size:32px;
                        color:#999;
                        font-weight:bold;
                    ">
                        No Feed Schedule Found
                    </div>
                `);

                return;
            }

            let schedule_names = r.message.map(d => d.name);

            let all_details = [];

            let pending = schedule_names.length;


            schedule_names.forEach(schedule_name => {

                frappe.call({

                    method: "frappe.client.get",

                    args: {
                        doctype: "Feed Schedule",
                        name: schedule_name
                    },

                    callback: function(res) {

                        let doc = res.message;

                        (doc.feed_schedule_detail || []).forEach(d => {
                            all_details.push(d);
                        });

                        pending--;

                        if (pending === 0) {
                            render_board(frm, all_details);
                        }

                    }

                });

            });

        }

    });

}





function render_board(frm, details) {

    let timings = [];

    if (frm.doc.shift_type === "Day Shift") {

        timings = [
            "10AM",
            "11AM",
            "12PM",
            "1PM",
            "2PM",
            "3PM",
            "4PM",
            "5PM",
            "6PM",
            "7PM",
            "8PM",
            "9PM"
        ];

    } else {

        timings = [
            "10PM",
            "11PM",
            "12AM",
            "1AM",
            "2AM",
            "3AM",
            "4AM",
            "5AM",
            "6AM",
            "7AM",
            "8AM",
            "9AM"
        ];

    }



    let grouped = {};

    details.forEach(d => {

        if (!grouped[d.tank]) {
            grouped[d.tank] = {};
