    let top = wrapper.find(".top-scroll");
    let bottom = wrapper.find(".table-scroll");
    
    // Match top scrollbar width with actual table width
    top.children("div").width(table.outerWidth());
    
    top.on("scroll", function () {
        bottom.scrollLeft($(this).scrollLeft());
    });
    
    bottom.on("scroll", function () {
        top.scrollLeft($(this).scrollLeft());
    });
    bind_actions(frm);

}





function get_selected_rows() {

    let rows = [];

    $('.feed-select:checked').each(function() {

        rows.push({
            name: $(this).attr('data-name'),
            qty: $(this).attr('data-qty'),
            uom: $(this).attr('data-uom')
        });

    });

    return rows;
}






function bind_actions(frm) {
    
    // Select / Unselect entire column
    
    $(frm.wrapper).find(".column-select").change(function () {
    
        let checked = $(this).prop("checked");
        let time = $(this).data("time");
    
        $(frm.wrapper)
            .find(`.feed-select[data-time="${time}"]`)
            .prop("checked", checked);
    
    });
    
    $(frm.wrapper).find(".done-btn").click(function () {
    
        let btn = $(this);
    
        btn.prop("disabled", true);
        btn.text("Processing...");
    
        let name = btn.attr("data-name");
        let qty = btn.attr("data-qty");
    
        frappe.call({
    
            method: "update_feed_execution",
    
            args: {
                row_name: name,
                status: "Done",
                actual_qty: qty,
                remarks: "",
                skip_reason: ""
            },
    
            callback: function () {
    
                frappe.show_alert({
                    message: "Feed Marked Done",
                    indicator: "green"
                });
    
                load_schedule(frm);
    
            },
            error: function () {

                btn.prop("disabled", false);
                btn.text("Done");
            
            }
    
        });
        

    
    });
    


    // SINGLE PARTIAL

    $(frm.wrapper).find(".partial-btn").click(function() {
        
        let btn = $(this);
        let name = $(this).attr("data-name");

        frappe.prompt([

            {
                fieldname: "actual_qty",
                label: "Actual Qty Fed",
                fieldtype: "Float",
                reqd: 1
            },

            {
                fieldname: "remarks",
                label: "Remarks",
                fieldtype: "Small Text"
            }

        ],
        

        
        function(values) {
            
            btn.prop("disabled", true);
            btn.text("Processing...");
            frappe.call({

                method: "update_feed_execution",

                args: {
                    row_name: name,
                    status: "Partial",
                    actual_qty: values.actual_qty,
                    remarks: values.remarks || "",
                    skip_reason: ""
                },

                callback: function() {

                    frappe.show_alert({
                        message: "Feed Marked Partial",
                        indicator: "orange"
                    });

                    load_schedule(frm);
                },
                error: function () {

                    btn.prop("disabled", false);
                    btn.text("Partial");
                
                }

            });

        },

        "Partial Feed Update",
        "Update"

        );

    });






    // SINGLE SKIP

    $(frm.wrapper).find(".skip-btn").click(function() {
        let btn = $(this);
        let name = $(this).attr("data-name");

        frappe.prompt([

            {
                fieldname: "skip_reason",
                label: "Skip Reason",
                fieldtype: "Small Text",
                reqd: 1
            }

        ],

        function(values) {
            btn.prop("disabled", true);
            btn.text("Processing...");
            frappe.call({

                method: "update_feed_execution",

                args: {
                    row_name: name,
                    status: "Skipped",
                    actual_qty: 0,
                    remarks: "",
                    skip_reason: values.skip_reason
                },

                callback: function() {

                    frappe.show_alert({
                        message: "Feed Marked Skipped",
                        indicator: "red"
                    });

                    load_schedule(frm);
                },
                error: function () {
                
                    btn.prop("disabled", false);
                    btn.text("Skip");
                
                }

            });

        },

        "Skip Feed",
        "Update"

        );

    });






    // BULK DONE

    $('.bulk-done-btn').click(function() {

        let rows = get_selected_rows();

        if (!rows.length) {
            frappe.msgprint("Select feeds first");
            return;
        }

        let pending = rows.length;

        rows.forEach(r => {
        
            frappe.call({
        
                method: "update_feed_execution",
        
                args: {
                    row_name: r.name,
                    status: "Done",
                    actual_qty: r.qty,
                    remarks: "",
                    skip_reason: ""
                },
        
                callback: function () {
        
                    pending--;
        
                    if (pending === 0) {
        
                        frappe.show_alert({
                            message: "Bulk Done Completed",
                            indicator: "green"
                        });
        
                        load_schedule(frm);
        
                    }
        
                }
        
            });
        
        });

    });







    // BULK PARTIAL

    $('.bulk-partial-btn').click(function() {

        let rows = get_selected_rows();

        if (!rows.length) {
            frappe.msgprint("Select feeds first");
            return;
        }

        frappe.prompt([

            {
                fieldname: "actual_qty",
                label: "Actual Qty",
                fieldtype: "Float",
                reqd: 1
            },

            {
                fieldname: "remarks",
                label: "Remarks",
                fieldtype: "Small Text"
            }

        ],

        function(values) {

            let pending = rows.length;

            rows.forEach(r => {
            
                frappe.call({
            
                    method: "update_feed_execution",
            
                    args: {
                        row_name: r.name,
                        status: "Partial",
                        actual_qty: values.actual_qty,
                        remarks: values.remarks || "",
                        skip_reason: ""
                    },
            
                    callback: function () {
            
                        pending--;
            
                        if (pending === 0) {
            
                            frappe.show_alert({
                                message: "Bulk Partial Completed",
                                indicator: "orange"
                            });
            
                            load_schedule(frm);
            
                        }
            
                    }
            
                });
            
            });

        },

        "Bulk Partial Update",
        "Update");

    });







    // BULK SKIP

    $('.bulk-skip-btn').click(function() {

        let rows = get_selected_rows();

        if (!rows.length) {
            frappe.msgprint("Select feeds first");
            return;
        }

        frappe.prompt([

            {
                fieldname: "skip_reason",
                label: "Skip Reason",
                fieldtype: "Small Text",
                reqd: 1
            }

        ],

        function(values) {

            let pending = rows.length;

            rows.forEach(r => {
            
                frappe.call({
            
                    method: "update_feed_execution",
            
                    args: {
                        row_name: r.name,
                        status: "Skipped",
                        actual_qty: 0,
                        remarks: "",
                        skip_reason: values.skip_reason
                    },
            
                    callback: function () {
            
                        pending--;
            
                        if (pending === 0) {
            
                            frappe.show_alert({
                                message: "Bulk Skip Completed",
                                indicator: "red"
                            });
            
                            load_schedule(frm);
            
                        }
            
                    }
            
                });
            
            });

        },

        "Bulk Skip",
        "Update");

    });

}

