function set_codes(frm) {

    // Shed Code
    if (frm.doc.shed) {

        let shed_code = frm.doc.shed.split("-").pop().trim();

        if (frm.doc.shed_code !== shed_code) {

            frm.set_value("shed_code", shed_code);
        }
    }

    // Shift Code
    let shift_map = {

        "Day Shift": "DS",
        "Night Shift": "NS"

    };

    let shift_code =
        shift_map[frm.doc.shift_type] || "GEN";

    if (frm.doc.shift_code !== shift_code) {

        frm.set_value("shift_code", shift_code);
    }

    // Day Code
    if (frm.doc.schedule_date) {

        let date_obj = frappe.datetime.str_to_obj(
            frm.doc.schedule_date
        );

        let day_code = String(
            date_obj.getDate()
        ).padStart(2, "0");

        if (frm.doc.day_code !== day_code) {

            frm.set_value("day_code", day_code);
        }
    }
}

