frappe.ui.form.on("Tank Stocking", {

    before_save: async function(frm) {

        // ONLY FOR NEW DOCS
        if (!frm.is_new()) {
            return;
        }

        let prefix = "TS";

        // =========================
        // SHED LETTER
        // =========================
        let shed = frm.doc.shed || "";

        let shed_letter = "";

        if (shed.includes("-")) {

            shed_letter = shed.split("-")[1].trim();

        } else {

            shed_letter = shed.trim();
        }

        // =========================
        // DAY
        // =========================
        let day = "";

        if (frm.doc.expected_start_date) {

            let d = new Date(frm.doc.expected_start_date);

            day = String(d.getDate()).padStart(2, "0");
        }

        // =========================
        // SERIAL
        // =========================
        let count = await frappe.db.count("Tank Stocking");

        let serial = String(count + 1).padStart(3, "0");

        // =========================
        // FINAL ID
        // =========================
        let final_id = `${prefix}-${shed_letter}-${day}-${serial}`;

        frm.set_value("custom_id", final_id);

    }

});

