let fetch_timer = null;

function fetch_previous_batch(frm) {

    if (!frm.doc.algae_batch || !frm.doc.algae_species)
        return;

    if (frm.doc.algae_batch === "0 hour Batch") {

        frm.set_value("previous_batch", "");

        frm.doc.stage_details.forEach(r => {
            r.no_of_units = 0;
        });

        frm.refresh_field("stage_details");
        return;
    }

    clearTimeout(fetch_timer);

    fetch_timer = setTimeout(() => {

        frappe.call({
            method: "get_previous_batch",
            freeze: false,
            args: {
                algae_batch: frm.doc.algae_batch,
                algae_species: frm.doc.algae_species
            },
            callback(r) {

                if (!r.message)
                    return;

                frm.set_value("previous_batch", r.message.previous_batch);

                frm.doc.stage_details.forEach((row, i) => {

                    row.no_of_units = r.message.rows[i]
                        ? r.message.rows[i].qty
                        : 0;

                });

                frm.refresh_field("stage_details");

            }
        });

    }, 100);

}



frappe.ui.form.on("Algae Production Batch", {

    algae_batch(frm) {

        // Clear previous values immediately
        frm.doc.stage_details.forEach(row => {

            row.no_of_units = 0;
            row.detained_units = 0;
            row.inoculated_units = 0;

        });

        frm.refresh_field("stage_details");

        fetch_previous_batch(frm);

    },

    algae_species(frm) {

        frm.doc.stage_details.forEach(row => {

            row.no_of_units = 0;
            row.detained_units = 0;
            row.inoculated_units = 0;

        });

        frm.refresh_field("stage_details");

        fetch_previous_batch(frm);

    }

});

frappe.ui.form.on("Algae Production Unit", {

    no_of_units(frm, cdt, cdn) {
        calculate_detained_units(frm, cdt, cdn);
    },

    inoculated_units(frm, cdt, cdn) {

        calculate_detained_units(frm, cdt, cdn);

        let row = locals[cdt][cdn];

        if (row.container_type !== "Cement Tank")
            return;

        generate_tank_rows(frm, cint(row.inoculated_units));

    }

});

