function generate_tank_rows(frm, count) {

    let current = frm.doc.tank_allocation.length;

    // Add rows if needed
    while (current < count) {
        frm.add_child("tank_allocation");
        current++;
    }

    // Remove extra rows if needed
    while (current > count) {
        frm.doc.tank_allocation.pop();
        current--;
    }

    frm.refresh_field("tank_allocation");
}

function calculate_detained_units(frm, cdt, cdn) {

    // if (frm.doc.algae_batch === "0 hour Batch") {
    //     return;
    // }

    let row = locals[cdt][cdn];

    let no_units = flt(row.no_of_units);
    let inoculated = flt(row.inoculated_units);

    // Only calculate if No. of Units is greater than 0
    if (no_units > 0) {
        row.detained_units = no_units - inoculated;
    } else {
        row.detained_units = 0;
    }

    frm.refresh_field("stage_details");
}



frappe.ui.form.on("Algae Tank Allocation", {

    current_water_volume(frm, cdt, cdn) {
        calculate_total_volume(frm, cdt, cdn);
