        calculate_total_volume(frm, cdt, cdn);
    }

});

function calculate_total_volume(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    row.total_volume =
        flt(row.current_water_volume) +
        flt(row.inoculated_algae);

    frm.refresh_field("tank_allocation");

}

