function box(label, fieldname, value, idx){

    return `
        <div class="box">

            <label>${label}</label>

            <input
                type="number"
                step="any"
                placeholder="0"
                class="tank-input"
                data-idx="${idx}"
                data-field="${fieldname}"
                value="${value || ""}"
            />

        </div>
    `;
