frappe.ui.form.on('Daily Micro Checks', {

    onload(frm) {
        set_latest_shrimp_cycle(frm);
        render_dashboard(frm, []);
    },

    refresh(frm) {

        render_dashboard(frm, frm.doc.tank_details || []);

        // if (frm.doc.shed) {
        //     render_dashboard(frm, frm.doc.tank_details || []);
        // }

    },

    observation_type(frm){

        toggle_observation_type(frm);

    },

    shed(frm) {

        frm.clear_table("tank_details");

        if (!frm.doc.shed) {

            render_dashboard(frm, []);
            return;

        }

        load_tanks(frm);

    },

    round(frm) {

        render_dashboard(frm, frm.doc.tank_details || []);
    }

});



