function render_dashboard(frm, tanks = []) {

    console.log("===== RENDER =====");
    console.log("Date :", frm.doc.date);
    console.log("Round:", frm.doc.round);
    console.log("Shed :", frm.doc.shed);
    console.log("Tank Count :", tanks.length);

    if (!frm.doc.shed) {

        frm.fields_dict.dashboard_html.$wrapper.html(`
            <div class="empty-dashboard">
                <div class="icon">🦐</div>
                <h3>Select Shed</h3>
            </div>
        `);

        return;
    }

    frm.fields_dict.dashboard_html.$wrapper.html(
        get_dashboard(frm, tanks)
    );
    toggle_observation_type(frm);
    bind_events(frm);

}

function toggle_observation_type(frm){

    const wrapper = frm.fields_dict.dashboard_html.$wrapper;

    const type = (frm.doc.observation_type || "").trim();

    console.log("Observation Type:", type);

    if(type === "Visual checks"){

        wrapper.find(".visual-section").show();
        wrapper.find(".micro-section").hide();
        wrapper.find(".numeric-section").show();

    }
    else if(type === "Micro checks"){

        wrapper.find(".visual-section").hide();
        wrapper.find(".micro-section").show();
        wrapper.find(".numeric-section").hide();

    }
    else{


        wrapper.find(".visual-section").show();
        wrapper.find(".micro-section").show();
        wrapper.find(".numeric-section").show();

    }

}

function get_dashboard(frm, tanks){

    let cards = "";
    let display_tanks = tanks;


    if (active_tab === "Pending") {

        display_tanks = tanks.filter(r =>
            !r.status || r.status === "Pending"
        );

    }

    else if (active_tab === "Flagged") {

        display_tanks = tanks.filter(r => r.status === "Flagged");

    }

    else if (active_tab === "Done") {

        display_tanks = tanks.filter(r => r.status === "Healthy");

    }

    const tab_count = display_tanks.length;

    const percent = tanks.length
        ? (tab_count / tanks.length) * 100
        : 0;


    display_tanks.forEach((row) => {

        const original_idx = frm.doc.tank_details.indexOf(row);

        cards += tank_card(row, original_idx);

    });

    console.log("get_dashboard");
    console.log(cards);

    return `



    <div class="tank-round">

        <div class="round-header">

            <div>

                <h2>Daily Tank Round</h2>

                <div class="subtitle">

                    ${frm.doc.shed}
                    •
                    ${frm.doc.shrimp_cycle}

                </div>

            </div>

            <div class="progress-box">

                <div class="count">

                    ${tab_count}/${tanks.length}

                </div>

                <div class="text">

                    Tanks Done

                </div>

            </div>

        </div>

        <div class="progress-bar">

            <div
                class="fill"
                style="width:${percent}%"
            ></div>

        </div>

        <div class="tabs">

            <button
                class="${active_tab=="All"?"active":""}"
                data-tab="All"
            >
                All
            </button>

            <button
                class="${active_tab=="Pending"?"active":""}"
                data-tab="Pending"
            >
                Pending
            </button>

            <button
                class="${active_tab=="Flagged"?"active":""}"
                data-tab="Flagged"
            >
                Flagged
            </button>

            <button
                class="${active_tab=="Done"?"active":""}"
                data-tab="Done"
            >
                Done
            </button>

        </div>

        ${cards}

    </div>

    `;


}

