function box(label, fieldname, value, idx){

    return `
        <div class="box">

            <label>${label}</label>

            <input
                type="number"
                step="any"
                placeholder="0"
                class="tank-input"
                data-idx="${idx}"
                data-field="${fieldname}"
                value="${value || ""}"
            />

        </div>
    `;
}


function select_box(label, fieldname, idx, value = "", status = ""){

    const options = SELECT_OPTIONS[fieldname] || [];

    let html = `
        <div class="select-box">

            <label>${label}</label>

            <select
                class="tank-select observation-input"
                data-idx="${idx}"
                data-field="${fieldname}"
                ${status === "Flagged" ? "" : "disabled"}
            >
                <option value="">Select</option>
    `;

    options.forEach(option => {

        html += `
            <option
                value="${option}"
                ${value === option ? "selected" : ""}
            >
                ${option}
            </option>
        `;

    });

    html += `
            </select>

        </div>
    `;

    return html;
}

function set_latest_shrimp_cycle(frm) {

    if (!frm.is_new()) return;

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Shrimp Batch",
            fields: ["name"],
            order_by: "creation desc",
            limit_page_length: 1
        },
        callback(r) {

            if (r.message && r.message.length) {

                frm.set_value("shrimp_cycle", r.message[0].name);

            }

        }
    });

}

function load_tanks(frm) {

    if (!frm.doc.shed) return;

    frappe.call({
        method: "get_daily_health_tanks",
        args: {
            shed: frm.doc.shed
        },
        freeze: true,
        callback(r) {

            const tanks = r.message || [];

            tanks.sort((a, b) => {
                return parseInt((b.tank || "").replace(/\D/g, "")) -
                       parseInt((a.tank || "").replace(/\D/g, ""));
            });

            frm.clear_table("tank_details");

            tanks.forEach(tank => {

                let row = frm.add_child("tank_details");

                row.tank = tank.tank;
                row.stage = tank.stage;
                row.population = tank.live;

            });

            frm.refresh_field("tank_details");

            render_dashboard(frm, frm.doc.tank_details);

        }
    });

}


function bind_events(frm) {

    const wrapper = frm.fields_dict.dashboard_html.$wrapper;

    wrapper.off();

    wrapper.on("change", ".tank-input", function () {

        const idx = $(this).data("idx");
        const field = $(this).data("field");

        let row = frm.doc.tank_details[idx];

        if (!row) return;

        row[field] = $(this).val();

        frm.dirty();

    });

    wrapper.on("change", ".tank-select", function () {

        const idx = $(this).data("idx");
        const field = $(this).data("field");

        let row = frm.doc.tank_details[idx];

        if (!row) return;

        row[field] = $(this).val();

        frm.dirty();

    });

    wrapper.on("click", ".green-btn", function () {

        const idx = $(this).data("idx");

        let row = frm.doc.tank_details[idx];

        if (!row) return;

        row.status = "Healthy";

        frm.dirty();

        render_dashboard(frm, frm.doc.tank_details);

    });

    wrapper.on("click", ".flag-btn", function () {

        const idx = $(this).data("idx");

        let row = frm.doc.tank_details[idx];

        if (!row) return;

        row.status = "Flagged";

        frm.dirty();

        render_dashboard(frm, frm.doc.tank_details);

    });

    wrapper.on("click", "[data-tab]", function () {

        active_tab = $(this).data("tab");

        render_dashboard(frm, frm.doc.tank_details);

    });



}

